-- ─────────────────────────────────────────────────────────────────────────
-- 2026-07-31 · Seværdigheder — katalog over oplevelser nær Castillo del Alma
--
-- Én række pr. seværdighed. Alle tekster ligger i JSONB-kolonnen `indhold`
-- med samme nøglemønster som gay_content: dansk i `nøgle`, engelsk i
-- `nøgle_en`. Det betyder, at admin-editoren, oversætterknappen og
-- fallback-logikken virker præcis som på de øvrige sider — men uden at der
-- skal oprettes en ny tabel for hver ny seværdighed.
--
-- Siden /sevaerdigheder/<slug> (og /en/sevaerdigheder/<slug>) læser slug'en
-- ud af adressen og henter den matchende række.
--
-- RLS følger samme mønster som de øvrige indholdstabeller efter fase 1:
-- alle må LÆSE (siden skal virke for besøgende), kun rollen 'authenticated'
-- må SKRIVE (admin er logget ind med en ægte Supabase-session).
-- RØR IKKE RLS på betalings-/kunde-tabeller.
--
-- Køres i Supabase SQL Editor. Idempotent — kan køres flere gange.
-- ─────────────────────────────────────────────────────────────────────────

create table if not exists public.sevaerdigheder (
  id          bigint generated by default as identity primary key,
  slug        text not null unique,
  titel       text,
  titel_en    text,
  aktiv       boolean not null default true,
  sort_orden  integer not null default 0,
  indhold     jsonb   not null default '{}'::jsonb,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

-- Opslaget på siden sker altid på slug + aktiv
create index if not exists sevaerdigheder_slug_idx   on public.sevaerdigheder (slug);
create index if not exists sevaerdigheder_aktiv_idx  on public.sevaerdigheder (aktiv, sort_orden);

-- updated_at vedligeholdes af databasen, så sitemappets <lastmod> altid
-- er sand — også når indholdet rettes fra admin.
create or replace function public.sevaerdigheder_touch()
returns trigger language plpgsql as $fn$
begin
  new.updated_at = now();
  return new;
end;
$fn$;

drop trigger if exists sevaerdigheder_touch_trg on public.sevaerdigheder;
create trigger sevaerdigheder_touch_trg
  before update on public.sevaerdigheder
  for each row execute function public.sevaerdigheder_touch();

-- Ryd eventuelle gamle policies, så filen kan køres igen uden fejl,
-- og slå RLS til. Samme fremgangsmåde som i RLS fase 1.
DO $$
DECLARE
  p record;
BEGIN
  FOR p IN
    SELECT policyname FROM pg_policies
    WHERE schemaname = 'public' AND tablename = 'sevaerdigheder'
  LOOP
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.sevaerdigheder', p.policyname);
  END LOOP;
END $$;

ALTER TABLE public.sevaerdigheder ENABLE ROW LEVEL SECURITY;

CREATE POLICY "alle_maa_laese" ON public.sevaerdigheder
  FOR SELECT TO anon, authenticated
  USING (true);

CREATE POLICY "kun_admin_maa_skrive" ON public.sevaerdigheder
  FOR ALL TO authenticated
  USING (true) WITH CHECK (true);

comment on table public.sevaerdigheder is
  'Katalog over seværdigheder og oplevelser nær Castillo del Alma. Én række '
  'pr. side; alle tekster i JSONB-kolonnen indhold (nøgler uden suffiks er '
  'danske, _en er engelske). Vises på /sevaerdigheder/<slug> og '
  '/en/sevaerdigheder/<slug>. Redigeres i admin under Sprog & Indhold → Seværdigheder.';


